#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int last[100001] = {0};
    int left = 1;
    int best = 0;

    for (int i = 1; i <= n; i++) {
        int value;
        scanf("%d", &value);

        if (last[value] >= left)
            left = last[value] + 1;

        last[value] = i;

        int length = i - left + 1;
        if (length > best) best = length;
    }

    printf("%d\n", best);
    return 0;
}
